-- Hand-written migration (not generated by drizzle-kit): things that live outside the Drizzle schema.

-- Public bucket for video thumbnails. These are covers of public videos, so nothing sensitive;
-- uploads happen server-side with the secret key.
insert into storage.buckets (id, name, public)
values ('thumbnails', 'thumbnails', true)
on conflict (id) do nothing;

-- audit_log is append-only: every money-relevant action stays on record.
create or replace function public.audit_log_block_changes()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'audit_log is append-only';
end;
$$;

create trigger audit_log_no_update_delete
before update or delete on public.audit_log
for each row execute function public.audit_log_block_changes();
